(() => {
  'use strict';
  const P=window.Portal,e=P.e,root='https://www.kraftringen.se/';
  const products={consumer:['Rörligt månadspris','Rörligt kvartspris','Kraftringen Opti'],business:['Rörligt månadspris','Rörligt kvartspris','Individuell indexportfölj','Kraftringen Stabil','Kraftringen Direkt','Poolportfölj – offensiv','Poolportfölj – trygg']};
  const items=[
    ['consumer','Rörligt månadspris','Ett elpris per kWh som fastställs i efterhand för månaden och följer marknaden.','Hushåll som vill följa marknaden utan att planera förbrukningen kvart för kvart.',['Enkel modell att följa månad för månad','Minskad elanvändning sänker kostnaden'],'Passar när enkelhet är viktigare än att styra användningen till vissa kvartar.','Priset kan stiga. Att flytta användning mellan kvartar sänker inte det egna månadspriset.','privat/el/vara-elavtal/rorligt-manadspris/'],
    ['consumer','Rörligt kvartspris','Energipriset följer spotmarknaden varje kvart och den egna elanvändningen.','Aktiva hushåll med flyttbar förbrukning, exempelvis laddning eller uppvärmning.',['Möjlighet att påverka kostnaden genom när elen används','Tydlig koppling mellan marknadspris och användning'],'Utgå från vad kunden faktiskt kan flytta till billigare kvartar.','Dyra kvartar kan höja kostnaden. Besparing är ingen garanti.','privat/el/vara-elavtal/rorligt-kvartspris/'],
    ['consumer','Kraftringen Opti','Kraftringen jämför utfallet av månadspris och kvartspris för kundens faktiska förbrukning och väljer det billigare alternativet.','Hushåll som vill kunna påverka förbrukningen men slippa välja mellan de två prismodellerna.',['Automatisk jämförelse inför fakturan','Möjlighet att dra nytta av flyttbar förbrukning'],'Två avtalsalternativ jämförs åt kunden – kunden behöver inte välja rätt modell i förväg.','Det är inte en garanti för marknadens lägsta pris eller ett fast pristak. Jämför även avgifterna.','privat/el/vara-elavtal/kraftringen-opti/'],
    ['business','Rörligt månadspris','Företagets elpris sätts månadsvis i efterskott. Marknadspris, rörliga kostnader och avtalade avgifter påverkar utfallet.','Företag som kan hantera prisvariationer och vill ha en enkel inköpsmodell.',['Följer marknaden','Ingen daglig styrning krävs för prismodellen'],'Börja med företagets budgetutrymme för svängande elkostnader.','Priset kan gå både upp och ned. Kontrollera företagets egna villkor.','foretag/el/vara-elavtal/rorligt-elpris/'],
    ['business','Rörligt kvartspris','Energikostnaden följer spotpriset och företagets användning i varje kvart.','Företag som kan planera eller styra delar av sin elanvändning.',['Påverkbar kostnad genom tidpunkt','Underlag för aktiv energistyrning'],'Kartlägg flyttbar last innan du beskriver möjliga besparingar.','Företagets exakta prisformel och produktblad behöver kompletteras.','', 'Befintligt utbildningsunderlag · företagsspecifika villkor saknas'],
    ['business','Individuell indexportfölj','En egen plan med successiva, regelstyrda inköp och prissäkringar för överenskomna månadsvolymer.','Elintensiva företag som behöver en inköpsplan anpassad till sin förbrukningsprofil.',['Inköp sprids över tid','Planen utgår från kundens volymer'],'Koppla upplägget till verksamhetens månadsprofil och önskade risknivå.','Webbkällan beskriver portföljförvaltning generellt. Exakt mandat, prisformel och horisont måste avtalas.','foretag/el/vara-elavtal/portfoljforvaltning/', 'Utbildningsunderlag + generell webbförklaring'],
    ['business','Kraftringen Stabil','Systempris och elområdesskillnad säkras vid ett tillfälle för överenskommen volym och period enligt projektets bekräftade utbildningsunderlag.','Företag som vill säkra dessa priskomponenter för en planerad förbrukningsprofil.',['Tydlighet för den säkrade delen','Förbrukningsprofilen vägs in i upplägget'],'Förklara exakt vilka komponenter och volymer som säkras.','Osäkrad el, dygnsprofil och andra kostnader ligger separat. Hela fakturan är inte fast.','', 'Bekräftat utbildningsunderlag · aktuellt produktblad behövs'],
    ['business','Kraftringen Direkt','Produkten finns i orderkatalogen. En verifierad produktbeskrivning saknas ännu.','Kompletteras av produktansvarig.',['Kundvärden kompletteras när produktbladet finns'],'Säljargument kompletteras efter bekräftad produktdefinition.','Anta inte prisformel, risknivå eller avtalsvillkor utifrån namnet.','', 'Underlag saknas'],
    ['business','Poolportfölj – offensiv','Gemensam inköpspool med successiv prissäkring och en aktivt förvaltad del enligt utbildningsunderlaget.','Företag som vill kombinera gemensam förvaltning med aktiva marknadsbeslut.',['Delad inköpsstrategi','Inköp sprids över tid'],'Beskriv möjligheten att agera på marknaden tillsammans med risken för sämre utfall.','Aktiv förvaltning kan ge både bättre och sämre resultat. Offertens mandat styr.','foretag/el/vara-elavtal/poolportfolj/', 'Utbildningsunderlag + generell webbförklaring'],
    ['business','Poolportfölj – trygg','Gemensam inköpspool med regelstyrda prissäkringar som byggs upp successivt enligt utbildningsunderlaget.','Företag som prioriterar spridda inköp och mindre beroende av en enda inköpstidpunkt.',['Gemensam förvaltning','Minskad koncentration av inköpsrisk över tid'],'Förklara hur successiva inköp kan jämna ut prisutvecklingen.','Ingen garanti om lägst pris eller helt fast slutkostnad. Offertens volymbas styr.','foretag/el/vara-elavtal/poolportfolj/', 'Utbildningsunderlag + generell webbförklaring']
  ].map(([category,name,description,fit,values,pitch,caution,source,basis])=>({category,name,description,fit,values,pitch,caution,source,basis:basis||'Webbunderlag kontrollerat 27 oktober 2026'}));
  // Explicit fictional examples only. Never import public historical spot prices as an offer.
  const priceLists=[
    {id:'standard-demo-v1',name:'Standard · exempelpriser',version:'1',date:'2026-10-27',partners:null,discount:0},
    {id:'face2face-demo-v1',name:'Face2face · exempelprislista',version:'1',date:'2026-10-27',partners:['vast'],discount:1},
    {id:'savera-demo-v1',name:'Savera · exempelprislista',version:'1',date:'2026-10-27',partners:['syd'],discount:1}
  ];
  const choices=new Map();let category=new URLSearchParams(location.search).get('factSegment')==='business'?'business':'consumer';
  const currentPartner=()=>P.role==='internal'?P.selectedPartnerId:P.partner;
  const key=(cat,name)=>cat+':'+name;
  const access=partner=>P.state.partnerProfiles?.[partner]?.catalogAccess;
  const allowedCategories=(partner=currentPartner())=>['sales','field'].includes(P.getPartner(partner)?.type)?['consumer','business'].filter(c=>P.getPartner(partner)?.salesAudiences?.includes(c)):[];
  const availableProducts=(cat,partner=currentPartner())=>!allowedCategories(partner).includes(cat)?[]:products[cat].filter(name=>access(partner)===undefined||Array.isArray(access(partner)?.products)&&access(partner).products.includes(key(cat,name)));
  const allowed=(cat,name,partner=P.partner)=>availableProducts(cat,partner).includes(name);
  const lists=(partner=currentPartner())=>priceLists.filter(l=>access(partner)===undefined?(!l.partners||l.partners.includes(partner)):Array.isArray(access(partner)?.priceLists)&&access(partner).priceLists.includes(l.id));
  function validateAccess(value){if(!value||!Array.isArray(value.products)||!Array.isArray(value.priceLists)||value.products.some(k=>!items.some(p=>key(p.category,p.name)===k))||value.priceLists.some(id=>!priceLists.some(l=>l.id===id)))return {ok:false,error:'Välj giltiga produkter och prislistor.'};return {ok:true,value:{products:[...new Set(value.products)],priceLists:[...new Set(value.priceLists)]}};}
  function restrictedOptions(pairs,value){return (!pairs.some(p=>p[0]===value)?`<option selected value="${e(value||'')}">${e(value||'Välj alternativ')} · inte tillgängligt</option>`:'')+pairs.map(([id,label])=>`<option value="${e(id)}"${id===value?' selected':''}>${e(label)}</option>`).join('');}
  function selected(partner=currentPartner()){const id=choices.get(partner);return lists(partner).some(l=>l.id===id)?id:(lists(partner)[0]?.id||'');}
  function select(id,partner=currentPartner()){if(!lists(partner).some(l=>l.id===id))return false;choices.set(partner,id);return true;}
  const getProduct=(cat,name)=>items.find(p=>p.category===cat&&p.name===name);
  function snapshot(id,cat,name,partner=P.partner){
    const list=lists(partner).find(l=>l.id===id),product=getProduct(cat,name);if(!list||!product||!allowed(cat,name,partner))return null;
    const quoted=cat==='business'&&!['Rörligt månadspris','Rörligt kvartspris'].includes(name);
    return {listId:list.id,listName:list.name,version:list.version,date:list.date,category:cat,product:name,demo:true,currency:'SEK',vat:cat==='consumer'?'inkl. moms':'exkl. moms',monthly:quoted?null:(name==='Kraftringen Opti'?119:cat==='consumer'?59:79)-list.discount*20,markup:quoted?null:(cat==='consumer'?5:6)-list.discount,energy:quoted?'Enligt individuell prisformel/offert':'Marknadsbaserad energidel och rörliga kostnader tillkommer',status:quoted?'Prisunderlag saknas':'Fiktivt räkneexempel'};
  }
  const number=n=>new Intl.NumberFormat('sv-SE',{maximumFractionDigits:2}).format(n);
  function priceHTML(s){if(!s)return '<p class="pc-missing">Prisreferens saknas.</p>';return `<div class="pc-price"><span class="eyebrow">${e(s.status)} · ${e(s.vat)}</span>${s.monthly===null?'<strong>Prisunderlag saknas</strong><p>Individuell offert behöver kompletteras.</p>':`<div class="pc-price-pair"><div><strong>${number(s.monthly)} <small>kr/mån</small></strong><span>Månadsavgift per anläggning</span></div><div><strong>${number(s.markup)} <small>öre/kWh</small></strong><span>Fast påslag</span></div></div>`}<p>${e(s.energy)}. Elnät och energiskatt ingår inte. Detta är inte ett totalt elpris.</p></div>`;}
  function listOptions(id,partner=currentPartner()){if(!lists(partner).length)return '<option value="">Ingen prislista tilldelad</option>';return lists(partner).map(l=>`<option value="${e(l.id)}"${l.id===id?' selected':''}>${e(l.name)}</option>`).join('');}
  function orderFields(draft){return `<label class="ow-field">Prislista *<select name="priceListId">${restrictedOptions(lists(P.partner).map(l=>[l.id,l.name]),draft.priceListId)}</select></label>`;}
  function orderPrice(draft){return `<section class="pc-order-price" aria-label="Orderns prisreferens"><strong>Vald prislista · endast exempelpriser</strong>${priceHTML(snapshot(draft.priceListId,draft.category,draft.product))}<small>Prislistans version och komponenter sparas med ordern. Inget bindande erbjudande skapas.</small></section>`;}
  function savedPrice(row){const s=row.priceSnapshot;return `<section class="pc-order-price"><h3>Sparad prisreferens</h3>${s?`<p>${e(s.listName)} · version ${e(s.version)} · ${e(s.date)}${s.demo?' · Fiktiva exempelpriser':''}</p>${priceHTML(s)}`:'<p>Äldre order · ingen prislista eller prisreferens sparad. Inga priser har lagts till i efterhand.</p>'}</section>`;}
  const lessonNames={'Rörligt kvartspris':'Kvartspris','Kraftringen Opti':'Opti','Individuell indexportfölj':'Individuell portfölj','Poolportfölj – offensiv':'Poolportfölj Offensiv','Poolportfölj – trygg':'Poolportfölj Trygg'};
  function factBody(p){const name=p.category==='business'&&p.name==='Rörligt månadspris'?'Rörligt pris':lessonNames[p.name]||p.name;return P.productFacts?.rows.find(r=>r[0]===p.category&&r[1]===name)?.[2]||'';}
  function materialLinks(p){
    const name=lessonNames[p.name]||p.name,lesson=P.productFacts?.lessons[name];
    const terms=root+(p.category==='consumer'?'privat':'foretag')+'/el/vara-elavtal/avtalsvillkor/';
    return `<div class="pc-material"><strong>Fördjupningsmaterial</strong>${lesson?`<a href="${e(P.productFacts.lessonHref(lesson[0],p.category))}">Se film och produktlektion →</a><a href="utbildning-preview/produktspecifikationer.pdf#page=${lesson[1]}" target="_blank" rel="noopener">Produktspecifikation · sida ${lesson[1]} ↗</a>`:'<span>Produktspecifikation och film behöver kompletteras.</span>'}<a href="${terms}" target="_blank" rel="noopener">Avtalsvillkor hos Kraftringen ↗</a></div>`;
  }
  const comparisons=[
    ['Månadsvis rörligt','Enkelhet','Minska mängden el','Marknadspriset varierar'],
    ['Spotpris per kvart','Flyttbar förbrukning','Flytta användningen','Dyra kvartar påverkar'],
    ['Billigast av månad/kvart','Automatisk jämförelse','Flytta eller minska','Inget fast pristak'],
    ['Månadsvis rörligt','Enkel inköpsmodell','Minska mängden el','Budgeten påverkas av priset'],
    ['Spotpris per kvart','Styrbar verksamhet','Flytta användningen','Exakta villkor saknas'],
    ['Successiva prissäkringar','Elintensiv verksamhet','Anpassad inköpsplan','Mandat och volym styr'],
    ['Säkring vid ett tillfälle','Planerad månadsprofil','Säkra valda komponenter','Hela fakturan är inte fast'],
    ['Underlag saknas','Behöver kompletteras','Underlag saknas','Villkor behöver bekräftas'],
    ['Pool med aktiv del','Aktiv gemensam förvaltning','Spridda inköp','Aktiva beslut kan slå fel'],
    ['Regelstyrd inköpspool','Spridda inköp','Minska tidskoncentration','Inget garanterat lägsta pris']
  ];
  const paths=['M4 5h16v15H4z M4 9h16 M8 3v4 M16 3v4','M12 3a9 9 0 1 0 0 18a9 9 0 0 0 0-18 M12 6v6l4 2','M4 8h15l-4-4 M20 16H5l4 4','M4 5h16v15H4z M4 9h16 M8 3v4 M16 3v4','M12 3a9 9 0 1 0 0 18a9 9 0 0 0 0-18 M12 6v6l4 2','M4 3v17h17 M7 15l4-5 4 2 5-7','M12 3l8 3v6c0 4-4 7-8 9-4-2-8-5-8-9V6z M8 12l3 3 5-6','M4 12h15 M14 7l5 5-5 5','M3 17l6-6 4 3 8-9 M15 5h6v6','M3 8l9-5 9 5-9 5z M3 12l9 5 9-5 M3 16l9 5 9-5'];
  const icon=p=>`<svg class="pc-icon" aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="${paths[items.indexOf(p)]}"/></svg>`;
  function comparison(rows,id){return `<section class="pc-comparison" aria-label="Produktjämförelse"><h2>Jämför ${category==='consumer'?'konsumentavtal':'företagsavtal'}</h2><p>Välj produktnamnet för detaljer. Avgifterna följer vald prislista · ${category==='consumer'?'inkl.':'exkl.'} moms. Fiktiva exempel, energikostnad tillkommer.</p><div class="pc-table-scroll" role="region" aria-label="Jämförelsetabell, bläddra i sidled på liten skärm" tabindex="0"><table><thead><tr><th scope="col">Produkt</th><th scope="col">Prismodell</th><th scope="col">Passar bäst</th><th scope="col">Påverkan</th><th scope="col">Att tänka på</th><th scope="col">Avgift / påslag</th></tr></thead><tbody>${rows.map(p=>{const price=snapshot(id,p.category,p.name,currentPartner()),c=comparisons[items.indexOf(p)];return `<tr><th scope="row"><button class="pc-jump" data-pc-jump="${items.indexOf(p)}">${icon(p)}<span>${e(p.name)}</span></button></th>${c.map(v=>`<td>${e(v)}</td>`).join('')}<td>${!price?'Ingen prislista':price.monthly===null?'Offertunderlag saknas':`${number(price.monthly)} kr/mån<br>${number(price.markup)} öre/kWh`}</td></tr>`;}).join('')}</tbody></table></div></section>`;}
  function render(){
    const cats=allowedCategories();if(!cats.includes(category))category=cats[0]||'consumer';const rows=items.filter(p=>p.category===category&&allowed(p.category,p.name,currentPartner()));const id=selected(),list=lists().find(l=>l.id===id);const canOrder=P.role==='partner'&&['sales','field'].includes(P.getPartner()?.type)&&!P.demoMode;
    return `<div class="ow-page pc-page"><header class="pc-heading"><div><span class="eyebrow">PRODUKTGUIDE / ELHANDEL</span><h1>Produkter</h1><p>Hitta rätt avtal för kunden – och gå direkt till ordern.</p></div>${P.role==='internal'?'<button class="btn btn-secondary" data-go="product-access">Partnerns produktsortiment →</button>':''}<button class="btn btn-secondary" data-go="academy">Utbildning →</button></header><section class="card pc-toolbar"><label>Prislista<select id="pc-price-list">${listOptions(id)}</select></label><div class="pc-categories" role="group" aria-label="Produktkategori">${[['consumer','Konsumenter'],['business','Företag']].filter(([id])=>cats.includes(id)).map(([id,label])=>`<button class="btn ${category===id?'btn-primary':'btn-secondary'}" data-pc-category="${id}" aria-pressed="${category===id}">${label} <span>${availableProducts(id).length}</span></button>`).join('')}</div></section><p class="pc-notice" role="status"><strong>Alla belopp är fiktiva exempelpriser.</strong> Energi, elnät och energiskatt tillkommer. Fastställda prislistor behöver kompletteras.</p>${rows.length?comparison(rows,id):'<p class="card pc-empty">Inga produkter är tilldelade i denna kategori. Kontakta Kraftringen.</p>'}<div class="pc-grid">${rows.map(p=>`<article id="pc-product-${items.indexOf(p)}" tabindex="-1" class="card pc-product"><div><span class="eyebrow">${category==='consumer'?'KONSUMENTER':'FÖRETAG'}</span><h2>${icon(p)}${e(p.name)}</h2><p>${e(p.description)}</p></div><div class="pc-fit"><h3>Passar bäst för</h3><p>${e(p.fit)}</p></div><h3>Kundvärden</h3><ul>${p.values.map(v=>`<li>${e(v)}</li>`).join('')}</ul><details><summary>Säljargument & att tänka på</summary><p><strong>I kundsamtalet:</strong> ${e(p.pitch)}</p><p><strong>Att tänka på:</strong> ${e(p.caution)}</p>${factBody(p)?`<p><strong>Avtalsfakta från befintligt underlag:</strong> ${e(factBody(p))}</p>`:''}<p class="muted">Målgrupp och säljargument är redaktionella förslag utifrån underlaget.</p><p>${e(p.basis)}</p>${p.source?`<a href="${root+p.source}" target="_blank" rel="noopener">Kraftringens produktbeskrivning ↗</a>`:''}${p.basis.includes('utbildningsunderlag')||p.basis.includes('Utbildningsunderlag')?'<p><a href="utbildning-preview/produktspecifikationer.pdf" target="_blank" rel="noopener">Befintlig produktspecifikation ↗</a></p>':''}</details>${materialLinks(p)}${priceHTML(snapshot(id,p.category,p.name,currentPartner()))}${canOrder&&list?`<button class="btn btn-primary pc-create" data-pc-order="${e(p.name)}" data-pc-segment="${p.category}" aria-label="Skapa order för ${e(p.name)}">Skapa order →</button>`:canOrder?'<p class="pc-missing">Ingen prislista är tilldelad. Kontakta Kraftringen för att kunna skapa en order.</p>':'<p class="muted">Öppna en säljpartners förhandsvisning för att skapa en exempelorder.</p>'}</article>`).join('')}</div><details class="card pc-archive"><summary>Fler avtalsformer i utbildningsmaterialet</summary><p>Fastpris och Vintersäkrat finns kvar som fördjupning. De ingår inte i den aktuella orderkatalogen.</p>${['Fastpris','Vintersäkrat'].map(name=>`<h3>${name}</h3><p>${e(factBody({name,category:'consumer'}))}</p>${materialLinks({name,category:'consumer'})}`).join('')}</details><p class="muted">Guiden visar partnerns tilldelade produkter. Samma urval gäller i orderformuläret. Produktnamn kan skilja sig från webbplatsens. <a href="${root}privat/el/vara-elpriser/" target="_blank" rel="noopener">Se aktuella publika konsumentpriser ↗</a></p></div>`;
  }
  function bind(){document.querySelectorAll('[data-pc-jump]').forEach(b=>b.onclick=()=>{const card=document.getElementById('pc-product-'+b.dataset.pcJump);card?.scrollIntoView({block:'start',behavior:'smooth'});card?.focus({preventScroll:true});});document.querySelector('#pc-price-list')?.addEventListener('change',ev=>{select(ev.target.value);P.render();document.querySelector('#pc-price-list')?.focus();});document.querySelectorAll('[data-pc-category]').forEach(b=>b.onclick=()=>{category=b.dataset.pcCategory;P.render();document.querySelector('[data-pc-category][aria-pressed="true"]')?.focus();});document.querySelectorAll('[data-pc-order]').forEach(b=>b.onclick=()=>{const cat=b.dataset.pcSegment,name=b.dataset.pcOrder;if(!getProduct(cat,name))return;P.orderWorkspace?.startProductOrder({category:cat,product:name,priceListId:selected()});});}
  P.productCatalog={products,items,lists,selected,select,snapshot,priceHTML,orderFields,orderPrice,savedPrice,key,allowedCategories,availableProducts,allowed,validateAccess,restrictedOptions};
  let accessPartner='';
  function renderAccess(){
    if(P.role!=='internal')return '<p>Partnerinställningar öppnas i Kraftringens interna vy.</p>';
    const partners=P.partnerRegistry.filter(p=>['sales','field'].includes(p.type));
    if(partners.some(p=>p.id===P.selectedPartnerId))accessPartner=P.selectedPartnerId;
    if(!partners.some(p=>p.id===accessPartner))accessPartner=partners[0]?.id;
    const partner=P.getPartner(accessPartner);if(!partner)return '<p>Skapa en säljpartner först.</p>';
    const cats=allowedCategories(accessPartner),chosen=items.filter(p=>availableProducts(p.category,accessPartner).includes(p.name)).map(p=>key(p.category,p.name));
    return `<div class="ow-page pc-page"><header class="pc-heading"><div><span class="eyebrow">KRAFTRINGEN / PARTNERINSTÄLLNINGAR</span><h1>Produkter och prislistor</h1></div><button class="btn btn-secondary" data-go="products">Till produktguiden →</button></header><p class="pc-notice">Demoinställningar sparas i denna webbläsare. De styr nya orderval; tidigare ordrar och sparade priser behålls. Detta är inte serverbaserad behörighet.</p><form id="pc-access-form" class="card pc-access"><label>Partner<select id="pc-access-partner">${partners.map(p=>`<option value="${e(p.id)}"${p.id===accessPartner?' selected':''}>${e(p.name)}</option>`).join('')}</select></label><div role="status" aria-live="polite" id="pc-access-message"></div><fieldset><legend>Kundkategorier som partnern får sälja till</legend>${[['consumer','Konsumenter'],['business','Företag']].map(([id,label])=>`<label><input type="checkbox" name="audience" value="${id}"${cats.includes(id)?' checked':''}>${label}</label>`).join('')}</fieldset><div class="pc-access-grid">${[['consumer','Konsumentprodukter'],['business','Företagsprodukter']].map(([cat,label])=>`<fieldset data-access-category="${cat}"><legend>${label}</legend>${items.filter(p=>p.category===cat).map(p=>`<label><input type="checkbox" name="product" value="${e(key(cat,p.name))}"${chosen.includes(key(cat,p.name))?' checked':''}>${icon(p)}${e(p.name)}</label>`).join('')}</fieldset>`).join('')}</div><fieldset><legend>Tillgängliga prislistor</legend>${priceLists.map(l=>`<label><input type="checkbox" name="priceList" value="${l.id}"${lists(accessPartner).some(v=>v.id===l.id)?' checked':''}>${e(l.name)}</label>`).join('')}</fieldset><p>Välj minst en kundkategori. Utan tilldelade produkter eller prislistor kan partnern inte skapa nya ordrar. Alla belopp är exempelpriser.</p><div class="ow-actions"><button class="btn btn-primary" type="submit">Spara partnerns sortiment</button><button class="btn btn-secondary" type="button" id="pc-access-reset">Återställ osparade val</button></div></form></div>`;
  }
  function bindAccess(){
    if(P.role!=='internal')return;const form=document.querySelector('#pc-access-form');if(!form)return;
    const update=()=>form.querySelectorAll('[data-access-category]').forEach(f=>{f.disabled=!form.querySelector(`[name="audience"][value="${f.dataset.accessCategory}"]`).checked;});update();
    form.querySelectorAll('[name="audience"]').forEach(el=>el.onchange=update);
    form.querySelector('#pc-access-partner').onchange=ev=>{accessPartner=ev.target.value;P.selectedPartnerId=accessPartner;P.go('product-access');};
    form.querySelector('#pc-access-reset').onclick=()=>P.render();
    form.onsubmit=ev=>{ev.preventDefault();const data=new FormData(form),partner=P.getPartner(accessPartner);const result=P.partnerSetup.saveProfile({name:partner.name,partnerType:'sales',salesAudiences:data.getAll('audience'),crmMode:partner.crmMode,catalogAccess:{products:data.getAll('product'),priceLists:data.getAll('priceList')}},accessPartner);if(result.ok){P.render();document.querySelector('#pc-access-message').textContent='Sparat. Partnerns produktguide och orderval är uppdaterade.';}else document.querySelector('#pc-access-message').textContent=result.error;};
  }
  P.register('product-access',{render:renderAccess,bind:bindAccess});
  P.register('products',{render,bind});
  // Old teaching links keep working; property-specific choices retain their original scope.
  const oldFacts=P.routes['product-facts'];
  const property=()=>P.role==='partner'&&P.getPartner()?.type==='property';
  P.register('product-facts',{render:()=>property()?oldFacts.render():render(),bind:()=>property()?oldFacts.bind?.():bind()});
})();
